HISTORIQUES = (
    (1593, 'Vecteur normal à une droite', 1, "La droite $d$ a pour équation $3x -1y +7 = 0$. Donner les coordonnées d'un vecteur normal à $d$.", '$\\vec{n}(3 ; -1)$', "Les coefficients de $x$ et $y$ dans l'équation $ax+by+c=0$ forment les coordonnées d'un vecteur normal.", ('Étape 1 : Si une droite a pour équation $ax+by+c=0$, alors le vecteur $\\vec{n}(a;b)$ est normal à cette droite.', 'Étape 2 : Ici $a=3$ et $b=-1$, donc $\\vec{n}(3 ; -1)$ est normal à $d$.')),
    (1594, 'Vecteur normal à une droite', 1, 'Déterminer une équation de la droite $d$ passant par le point $A(-5 ; 6)$ et de vecteur normal $\\vec{n}(4 ; 2)$.', '$d : 4x +2y +8 = 0$', 'Utiliser $a(x-x_A)+b(y-y_A)=0$ avec $\\vec{n}(a;b)$ normal à $d$.', ('Étape 1 : Une droite de vecteur normal $\\vec{n}(a;b)$ passant par $A(x_A;y_A)$ a pour équation $a(x-x_A)+b(y-y_A)=0$.', 'Étape 2 : $d : 4(x-(-5)) + 2(y-(6)) = 0$.', 'Étape 3 : En développant, $d : 4x +2y +8 = 0$.')),
    (1595, 'Vecteur normal à une droite', 1, "La droite $d$ a pour équation $4x +2y -6 = 0$. Donner les coordonnées d'un vecteur normal à $d$.", '$\\vec{n}(4 ; 2)$', "Les coefficients de $x$ et $y$ dans l'équation $ax+by+c=0$ forment les coordonnées d'un vecteur normal.", ('Étape 1 : Si une droite a pour équation $ax+by+c=0$, alors le vecteur $\\vec{n}(a;b)$ est normal à cette droite.', 'Étape 2 : Ici $a=4$ et $b=2$, donc $\\vec{n}(4 ; 2)$ est normal à $d$.')),
    (1602, 'Vecteur normal à une droite', 1, "La droite $d$ a pour équation $1x -5y -10 = 0$. Donner les coordonnées d'un vecteur normal à $d$.", '$\\vec{n}(1 ; -5)$', "Les coefficients de $x$ et $y$ dans l'équation $ax+by+c=0$ forment les coordonnées d'un vecteur normal.", ('Étape 1 : Si une droite a pour équation $ax+by+c=0$, alors le vecteur $\\vec{n}(a;b)$ est normal à cette droite.', 'Étape 2 : Ici $a=1$ et $b=-5$, donc $\\vec{n}(1 ; -5)$ est normal à $d$.')),
    (1611, 'Vecteur normal à une droite', 2, "La droite $d$ a pour équation $3x +6y +4 = 0$. Donner les coordonnées d'un vecteur normal à $d$.", '$\\vec{n}(3 ; 6)$', "Les coefficients de $x$ et $y$ dans l'équation $ax+by+c=0$ forment les coordonnées d'un vecteur normal.", ('Étape 1 : Si une droite a pour équation $ax+by+c=0$, alors le vecteur $\\vec{n}(a;b)$ est normal à cette droite.', 'Étape 2 : Ici $a=3$ et $b=6$, donc $\\vec{n}(3 ; 6)$ est normal à $d$.')),
    (1652, "Équation d'un cercle", 1, "On donne l'équation $\\mathcal{C} : x^2+y^2 -6x -10y +30 = 0$. Montrer qu'il s'agit de l'équation d'un cercle dont on précisera le centre et le rayon.", 'Cercle de centre $\\Omega(3 ; 5)$ et de rayon $2$', 'Faire apparaître deux formes canoniques $(x-a)^2$ et $(y-b)^2$ en regroupant les termes en $x$ puis en $y$.', ('Étape 1 : On regroupe : $x^2 -6x + y^2 -10y +30 = 0$.', 'Étape 2 : On met sous forme canonique chaque groupe : $(x-3)^2 - 9 + (y-5)^2 - 25 +30 = 0$.', "Étape 3 : D'où $(x-3)^2+(y-5)^2 = 4$ (car $9+25-30 = 4$).", "Étape 4 : C'est l'équation d'un cercle de centre $\\Omega(3 ; 5)$ et de rayon $2$.")),
    (1653, "Équation d'un cercle", 1, 'Donner une équation du cercle de diamètre $[AB]$ où $A(-3 ; 6)$ et $B(-2 ; 1)$.', '$\\left(x+\\dfrac{5}{2}\\right)^2+\\left(y-\\dfrac{7}{2}\\right)^2 = \\dfrac{13}{2}$', 'Le centre est le milieu de $[AB]$ et le rayon est la moitié de $AB$.', ('Étape 1 : Le centre du cercle est le milieu $\\Omega$ de $[AB]$ : $\\Omega\\left(-\\dfrac{5}{2} ; \\dfrac{7}{2}\\right)$.', 'Étape 2 : Le rayon au carré vaut $r^2 = \\left(\\dfrac{AB}{2}\\right)^2 = \\dfrac{13}{2}$.', "Étape 3 : L'équation du cercle est $\\left(x+\\dfrac{5}{2}\\right)^2+\\left(y-\\dfrac{7}{2}\\right)^2 = \\dfrac{13}{2}$.")),
    (1654, "Équation d'un cercle", 1, "On donne l'équation $\\mathcal{C} : x^2+y^2 +8x -4y -44 = 0$. Montrer qu'il s'agit de l'équation d'un cercle dont on précisera le centre et le rayon.", 'Cercle de centre $\\Omega(-4 ; 2)$ et de rayon $8$', 'Faire apparaître deux formes canoniques $(x-a)^2$ et $(y-b)^2$ en regroupant les termes en $x$ puis en $y$.', ('Étape 1 : On regroupe : $x^2 +8x + y^2 -4y -44 = 0$.', 'Étape 2 : On met sous forme canonique chaque groupe : $(x+4)^2 - 16 + (y-2)^2 - 4 -44 = 0$.', "Étape 3 : D'où $(x+4)^2+(y-2)^2 = 64$ (car $16+4+44 = 64$).", "Étape 4 : C'est l'équation d'un cercle de centre $\\Omega(-4 ; 2)$ et de rayon $8$.")),
    (1659, "Équation d'un cercle", 1, 'Donner une équation du cercle $\\mathcal{C}$ de centre $\\Omega(3 ; -7)$ et de rayon $2$.', '$\\mathcal{C} : (x-(3))^2+(y-(-7))^2 = 4$', 'Utiliser la forme $(x-a)^2+(y-b)^2=r^2$.', ('Étape 1 : Un cercle de centre $\\Omega(a;b)$ et de rayon $r$ a pour équation $(x-a)^2+(y-b)^2=r^2$.', 'Étape 2 : Ici, $\\mathcal{C} : (x-(3))^2+(y-(-7))^2 = 4$.')),
    (1664, "Équation d'un cercle", 2, "On donne l'équation $\\mathcal{C} : x^2+y^2 -6x +0y -7 = 0$. Montrer qu'il s'agit de l'équation d'un cercle dont on précisera le centre et le rayon.", 'Cercle de centre $\\Omega(3 ; 0)$ et de rayon $4$', 'Faire apparaître deux formes canoniques $(x-a)^2$ et $(y-b)^2$ en regroupant les termes en $x$ puis en $y$.', ('Étape 1 : On regroupe : $x^2 -6x + y^2 +0y -7 = 0$.', 'Étape 2 : On met sous forme canonique chaque groupe : $(x-3)^2 - 9 + (y-0)^2 - 0 -7 = 0$.', "Étape 3 : D'où $(x-3)^2+(y-0)^2 = 16$ (car $9+0+7 = 16$).", "Étape 4 : C'est l'équation d'un cercle de centre $\\Omega(3 ; 0)$ et de rayon $4$.")),
    (1668, "Équation d'un cercle", 2, "On donne l'équation $\\mathcal{C} : x^2+y^2 +12x +4y +31 = 0$. Montrer qu'il s'agit de l'équation d'un cercle dont on précisera le centre et le rayon.", 'Cercle de centre $\\Omega(-6 ; -2)$ et de rayon $3$', 'Faire apparaître deux formes canoniques $(x-a)^2$ et $(y-b)^2$ en regroupant les termes en $x$ puis en $y$.', ('Étape 1 : On regroupe : $x^2 +12x + y^2 +4y +31 = 0$.', 'Étape 2 : On met sous forme canonique chaque groupe : $(x+6)^2 - 36 + (y+2)^2 - 4 +31 = 0$.', "Étape 3 : D'où $(x+6)^2+(y+2)^2 = 9$ (car $36+4-31 = 9$).", "Étape 4 : C'est l'équation d'un cercle de centre $\\Omega(-6 ; -2)$ et de rayon $3$.")),
    (1677, "Équation d'un cercle", 3, "On donne l'équation $\\mathcal{C} : x^2+y^2 -10x +6y +18 = 0$. Montrer qu'il s'agit de l'équation d'un cercle dont on précisera le centre et le rayon.", 'Cercle de centre $\\Omega(5 ; -3)$ et de rayon $4$', 'Faire apparaître deux formes canoniques $(x-a)^2$ et $(y-b)^2$ en regroupant les termes en $x$ puis en $y$.', ('Étape 1 : On regroupe : $x^2 -10x + y^2 +6y +18 = 0$.', 'Étape 2 : On met sous forme canonique chaque groupe : $(x-5)^2 - 25 + (y+3)^2 - 9 +18 = 0$.', "Étape 3 : D'où $(x-5)^2+(y+3)^2 = 16$ (car $25+9-18 = 16$).", "Étape 4 : C'est l'équation d'un cercle de centre $\\Omega(5 ; -3)$ et de rayon $4$.")),
    (1682, "Équation d'un cercle", 3, "On donne l'équation $\\mathcal{C} : x^2+y^2 +10x -4y +4 = 0$. Montrer qu'il s'agit de l'équation d'un cercle dont on précisera le centre et le rayon.", 'Cercle de centre $\\Omega(-5 ; 2)$ et de rayon $5$', 'Faire apparaître deux formes canoniques $(x-a)^2$ et $(y-b)^2$ en regroupant les termes en $x$ puis en $y$.', ('Étape 1 : On regroupe : $x^2 +10x + y^2 -4y +4 = 0$.', 'Étape 2 : On met sous forme canonique chaque groupe : $(x+5)^2 - 25 + (y-2)^2 - 4 +4 = 0$.', "Étape 3 : D'où $(x+5)^2+(y-2)^2 = 25$ (car $25+4-4 = 25$).", "Étape 4 : C'est l'équation d'un cercle de centre $\\Omega(-5 ; 2)$ et de rayon $5$.")),
    (1683, "Équation d'un cercle", 3, "On donne l'équation $\\mathcal{C} : x^2+y^2 +2x +2y -7 = 0$. Montrer qu'il s'agit de l'équation d'un cercle dont on précisera le centre et le rayon.", 'Cercle de centre $\\Omega(-1 ; -1)$ et de rayon $3$', 'Faire apparaître deux formes canoniques $(x-a)^2$ et $(y-b)^2$ en regroupant les termes en $x$ puis en $y$.', ('Étape 1 : On regroupe : $x^2 +2x + y^2 +2y -7 = 0$.', 'Étape 2 : On met sous forme canonique chaque groupe : $(x+1)^2 - 1 + (y+1)^2 - 1 -7 = 0$.', "Étape 3 : D'où $(x+1)^2+(y+1)^2 = 9$ (car $1+1+7 = 9$).", "Étape 4 : C'est l'équation d'un cercle de centre $\\Omega(-1 ; -1)$ et de rayon $3$.")),
    (2139, 'Vecteur normal à une droite', 1, "La droite $d$ a pour équation $5x -3y +8 = 0$. Donner les coordonnées d'un vecteur normal à $d$.", '$\\vec{n}(5 ; -3)$', 'Si $d : ax+by+c=0$, alors $\\vec{n}(a ; b)$ est un vecteur normal à $d$.', ("Étape 1 : L'équation de $d$ est de la forme $ax+by+c=0$ avec $a=5$ et $b=-3$.", 'Étape 2 : Un vecteur normal à $d$ est donc $\\vec{n}(5 ; -3)$.')),
    (2140, 'Vecteur normal à une droite', 1, "La droite $d$ a pour équation $-2x +7y -4 = 0$. Donner les coordonnées d'un vecteur normal à $d$.", '$\\vec{n}(-2 ; 7)$', 'Si $d : ax+by+c=0$, alors $\\vec{n}(a ; b)$ est un vecteur normal à $d$.', ("Étape 1 : L'équation de $d$ est de la forme $ax+by+c=0$ avec $a=-2$ et $b=7$.", 'Étape 2 : Un vecteur normal à $d$ est donc $\\vec{n}(-2 ; 7)$.')),
    (2141, 'Vecteur normal à une droite', 2, "La droite $d$ a pour équation $6x +1y -9 = 0$. Donner les coordonnées d'un vecteur normal à $d$.", '$\\vec{n}(6 ; 1)$', 'Si $d : ax+by+c=0$, alors $\\vec{n}(a ; b)$ est un vecteur normal à $d$.', ("Étape 1 : L'équation de $d$ est de la forme $ax+by+c=0$ avec $a=6$ et $b=1$.", 'Étape 2 : Un vecteur normal à $d$ est donc $\\vec{n}(6 ; 1)$.')),
    (2142, 'Vecteur normal à une droite', 2, 'Déterminer une équation de la droite $d$ passant par le point $A(2 ; -3)$ et de vecteur normal $\\vec{n}(5 ; -1)$.', '$d : 5x -1y -13 = 0$', 'Une équation de $d$ est $n_x(x-x_A)+n_y(y-y_A)=0$.', ('Étape 1 : Une équation de $d$ est $5(x-(2))+-1(y-(-3))=0$.', 'Étape 2 : En développant : $5x -10 -1y -3 = 0$, soit $5x -1y -13 = 0$.')),
    (2143, 'Vecteur normal à une droite', 1, 'Déterminer une équation de la droite $d$ passant par le point $A(-4 ; 6)$ et de vecteur normal $\\vec{n}(3 ; 7)$.', '$d : 3x +7y -30 = 0$', 'Une équation de $d$ est $n_x(x-x_A)+n_y(y-y_A)=0$.', ('Étape 1 : Une équation de $d$ est $3(x-(-4))+7(y-(6))=0$.', 'Étape 2 : En développant : $3x +12 +7y -42 = 0$, soit $3x +7y -30 = 0$.')),
    (2144, 'Vecteur normal à une droite', 2, 'Déterminer une équation de la droite $d$ passant par le point $A(1 ; 1)$ et de vecteur normal $\\vec{n}(-2 ; 4)$.', '$d : -2x +4y -2 = 0$', 'Une équation de $d$ est $n_x(x-x_A)+n_y(y-y_A)=0$.', ('Étape 1 : Une équation de $d$ est $-2(x-(1))+4(y-(1))=0$.', 'Étape 2 : En développant : $-2x +2 +4y -4 = 0$, soit $-2x +4y -2 = 0$.')),
    (2145, 'Vecteur normal à une droite', 2, "La droite $d$ d'équation $3x -2y + c = 0$ passe par le point $A(4 ; 1)$. Déterminer la valeur de $c$.", '$c = -10$', "Le point $A$ appartient à $d$, donc ses coordonnées vérifient l'équation de $d$.", ('Étape 1 : Comme $A \\in d$, on a $3\\times4 -2 + c = 0$.', 'Étape 2 : $10 + c = 0 \\iff c = -10$.')),
    (2146, 'Vecteur normal à une droite', 3, "La droite $d$ d'équation $5x +4y + c = 0$ passe par le point $A(-1 ; 2)$. Déterminer la valeur de $c$.", '$c = -3$', "Le point $A$ appartient à $d$, donc ses coordonnées vérifient l'équation de $d$.", ('Étape 1 : Comme $A \\in d$, on a $5\\times-1 +8 + c = 0$.', 'Étape 2 : $3 + c = 0 \\iff c = -3$.')),
    (2147, 'Vecteur normal à une droite', 2, 'Les droites $d_1 : 2x -5y +3 = 0$ et $d_2 : 4x +my +7 = 0$ sont parallèles. Déterminer la valeur de $m$.', '$m = -10$', 'Deux droites sont parallèles si, et seulement si, leurs vecteurs normaux sont colinéaires.', ('Étape 1 : $\\vec{n_1}(2 ; -5)$ est un vecteur normal à $d_1$, et $\\vec{n_2}(4 ; m)$ un vecteur normal à $d_2$.', 'Étape 2 : $d_1$ et $d_2$ sont parallèles si, et seulement si, $\\vec{n_1}$ et $\\vec{n_2}$ sont colinéaires, donc $\\dfrac{4}{2} = \\dfrac{m}{-5}$.', 'Étape 3 : $\\dfrac{4}{2} = 2$, donc $m = 2\\times-5 = -10$.')),
    (2148, 'Vecteur normal à une droite', 3, 'Les droites $d_1 : -3x +4y +6 = 0$ et $d_2 : -9x +my -1 = 0$ sont parallèles. Déterminer la valeur de $m$.', '$m = 12$', 'Deux droites sont parallèles si, et seulement si, leurs vecteurs normaux sont colinéaires.', ('Étape 1 : $\\vec{n_1}(-3 ; 4)$ est un vecteur normal à $d_1$, et $\\vec{n_2}(-9 ; m)$ un vecteur normal à $d_2$.', 'Étape 2 : $d_1$ et $d_2$ sont parallèles si, et seulement si, $\\vec{n_1}$ et $\\vec{n_2}$ sont colinéaires, donc $\\dfrac{-9}{-3} = \\dfrac{m}{4}$.', 'Étape 3 : $\\dfrac{-9}{-3} = 3$, donc $m = 3\\times4 = 12$.')),
    (2149, 'Vecteur normal à une droite', 3, 'Vrai ou faux ? La droite $d$ a pour équation $4x -6y +5 = 0$. Le vecteur $\\vec{w}(-2 ; 3)$ est un vecteur normal à $d$. Justifier.', 'Vrai', "$\\vec{w}$ est normal à $d$ si, et seulement si, $\\vec{w}$ est colinéaire au vecteur $\\vec{n}(4 ; -6)$ lu directement sur l'équation.", ('Étape 1 : Un vecteur normal évident est $\\vec{n}(4 ; -6)$.', 'Étape 2 : $\\vec{w}(-2 ; 3)$ vérifie $\\vec{n} = -2\\,\\vec{w}$ (ou $x_n y_w - x_w y_n = 4\\times3 - (-2)\\times(-6) = 12-12=0$) : $\\vec{w}$ et $\\vec{n}$ sont colinéaires.', "Étape 3 : $\\vec{w}$ est donc bien un vecteur normal à $d$. L'affirmation est vraie.")),
    (2150, 'Vecteur normal à une droite', 3, 'Vrai ou faux ? La droite $d$ a pour équation $3x +5y -2 = 0$. Le vecteur $\\vec{w}(5 ; 3)$ est un vecteur normal à $d$. Justifier.', 'Faux', "$\\vec{w}$ est normal à $d$ si, et seulement si, $\\vec{w}$ est colinéaire au vecteur $\\vec{n}(3 ; 5)$ lu directement sur l'équation.", ('Étape 1 : Un vecteur normal évident est $\\vec{n}(3 ; 5)$.', 'Étape 2 : $x_n y_w - x_w y_n = 3\\times3 - 5\\times5 = 9-25 = -16 \\neq 0$ : $\\vec{w}$ et $\\vec{n}$ ne sont pas colinéaires.', "Étape 3 : $\\vec{w}$ n'est donc pas un vecteur normal à $d$ (il a simplement les coordonnées de $\\vec{n}$ échangées, ce qui donne un vecteur directeur, pas normal). L'affirmation est fausse.")),
    (2151, 'Vecteur normal à une droite', 3, 'Pour la droite $d : 7x -2y +5 = 0$, un élève affirme : « un vecteur normal à $d$ est $\\vec{n}(-2 ; 7)$ ». Identifier et corriger son erreur.', 'Un vecteur normal à $d$ est $\\vec{n}(7 ; -2)$', 'Sur une équation $ax+by+c=0$, le vecteur normal est $\\vec{n}(a;b)$, pas $(b;a)$ ni $(-b;a)$.', ("Étape 1 : L'élève a inversé (et changé le signe d'une) les coordonnées : $\\vec{n}(-2;7)$ est en réalité un vecteur directeur de $d$, pas un vecteur normal.", "Étape 2 : Sur l'équation $7x-2y+5=0$, le vecteur normal se lit directement : $\\vec{n}(a;b) = \\vec{n}(7;-2)$.", 'Étape 3 : Le vecteur normal correct est donc $\\vec{n}(7 ; -2)$, et $\\vec{n}(-2;7)$ (obtenu en échangeant les coordonnées et en changeant un signe) est le vecteur directeur associé.')),
    (2152, 'Vecteur normal à une droite', 3, "Pour déterminer l'équation de la droite $d$ passant par $A(3 ; -1)$ de vecteur normal $\\vec{n}(2 ; 5)$, un élève écrit : « $d : 2x+5y+3-1=0$, soit $2x+5y+2=0$ ». Identifier et corriger son erreur.", '$d : 2x +5y -1 = 0$', "L'équation correcte est $n_x(x-x_A)+n_y(y-y_A)=0$, il faut développer chaque terme séparément, pas simplement ajouter les coordonnées de $A$.", ("Étape 1 : L'élève a directement ajouté les coordonnées de $A$ au lieu de calculer $n_x(x-x_A)+n_y(y-y_A)$.", 'Étape 2 : Le calcul correct est $2(x-3)+5(y-(-1))=0$, soit $2x-6+5y+5=0$.', "Étape 3 : En simplifiant : $2x+5y-1=0$. L'équation correcte est donc $d : 2x+5y-1=0$, et non $2x+5y+2=0$.")),
    (2153, 'Vecteur normal à une droite', 2, 'On donne les points $A(1 ; 4)$ et $B(5 ; -2)$. Déterminer une équation de la droite $d$ passant par $A$ et de vecteur normal $\\vec{AB}$.', '$d : 4x -6y +20 = 0$', "Calculer d'abord les coordonnées de $\\vec{AB}$, puis utiliser $n_x(x-x_A)+n_y(y-y_A)=0$.", ('Étape 1 : $\\vec{AB}(4 ; -6)$.', 'Étape 2 : Une équation de $d$ est $4(x-(1))+-6(y-(4))=0$.', 'Étape 3 : En développant, on obtient $4x -6y +20 = 0$.')),
    (2154, 'Vecteur normal à une droite', 3, 'On donne les points $A(-3 ; 0)$ et $B(3 ; 4)$. Déterminer une équation de la droite $d$ passant par $A$ et de vecteur normal $\\vec{AB}$.', '$d : 6x +4y +18 = 0$', "Calculer d'abord les coordonnées de $\\vec{AB}$, puis utiliser $n_x(x-x_A)+n_y(y-y_A)=0$.", ('Étape 1 : $\\vec{AB}(6 ; 4)$.', 'Étape 2 : Une équation de $d$ est $6(x-(-3))+4(y-(0))=0$.', 'Étape 3 : En développant, on obtient $6x +4y +18 = 0$.')),
    (2155, 'Vecteur normal à une droite', 2, "Une antenne relais émet un signal dont le front d'onde, à un instant donné, est modélisé par une droite $d$ de vecteur normal $\\vec{n}(3 ; 4)$ (la direction de propagation du signal). Cette droite passe par le point $A(2 ; 1)$ (position en kilomètres). Donner une équation de $d$.", '$d : 3x +4y -10 = 0$', 'Utiliser $n_x(x-x_A)+n_y(y-y_A)=0$.', ('Étape 1 : Une équation de $d$ est $3(x-2)+4(y-1)=0$.', 'Étape 2 : En développant : $3x-6+4y-4=0$, soit $3x+4y-10=0$.')),
    (2156, 'Vecteur normal à une droite', 2, "Une rue rectiligne est modélisée par la droite $d : 5x -2y +8 = 0$ (coordonnées en centaines de mètres). Un urbaniste veut installer une conduite d'eau strictement perpendiculaire à cette rue en chaque point. Donner les coordonnées d'un vecteur directeur de cette conduite.", '$\\vec{n}(5 ; -2)$ convient comme vecteur directeur de la conduite', 'Une droite perpendiculaire à $d$ a pour vecteur directeur un vecteur normal à $d$.', ("Étape 1 : Un vecteur normal à $d$ est $\\vec{n}(5 ; -2)$ (lu directement sur l'équation).", 'Étape 2 : Une droite perpendiculaire à $d$ admet ce vecteur normal comme vecteur directeur : la conduite peut donc être dirigée par $\\vec{n}(5 ; -2)$.')),
    (2157, 'Vecteur normal à une droite', 4, "La droite $d$ passe par $A(2 ; 5)$ et $B(6 ; 3)$. Un élève détermine un vecteur normal à $d$ en faisant tourner le vecteur directeur $\\vec{AB}$ ; un autre élève trouve d'abord une équation de $d$ avec la formule $(y-y_A)(x_B-x_A) - (x-x_A)(y_B-y_A) = 0$, puis lit le vecteur normal sur cette équation. Mener les deux méthodes et comparer les résultats.", 'Les deux méthodes donnent le même vecteur normal, colinéaire à $\\vec{n}(1 ; 2)$', 'Un vecteur normal à $d$ est orthogonal au vecteur directeur $\\vec{AB}$ : si $\\vec{AB}(a;b)$, alors $\\vec{n}(-b;a)$ (ou $\\vec{n}(b;-a)$) convient.', ('Étape 1 (méthode directe) : $\\vec{AB}(4 ; -2)$ est un vecteur directeur de $d$ ; en le faisant tourner de $90°$, un vecteur normal est $\\vec{n}(2 ; 4)$, colinéaire à $\\vec{n}(1;2)$.', "Étape 2 (méthode par l'équation) : $(y-5)\\times4 - (x-2)\\times(-2) = 0$ donne $4y-20+2x-4=0$, soit $2x+4y-24=0$.", 'Étape 3 : Sur cette équation, le vecteur normal se lit directement : $\\vec{n}(2;4)$, colinéaire à $\\vec{n}(1;2)$. Les deux méthodes concordent bien.')),
    (2158, 'Vecteur normal à une droite', 4, "Soit $d$ la droite d'équation $ax+by+c=0$ (avec $(a;b) \\neq (0;0)$) et $\\vec{n}(a;b)$. Démontrer que $\\vec{n}$ est orthogonal à tout vecteur directeur $\\vec{u}(-b;a)$ de $d$, ce qui justifie que $\\vec{n}$ est un vecteur normal à $d$.", 'Propriété démontrée : $\\vec{n}\\cdot\\vec{u} = 0$', 'Calculer le produit scalaire $\\vec{n}\\cdot\\vec{u}$ avec les coordonnées littérales.', ('Étape 1 : $\\vec{u}(-b;a)$ est bien un vecteur directeur de $d$ : en effet, pour deux points $M_1(x_1;y_1)$ et $M_2(x_2;y_2)$ de $d$, on a $a(x_2-x_1)+b(y_2-y_1)=0$, donc le vecteur $\\vec{M_1M_2}(x_2-x_1;y_2-y_1)$ est colinéaire à $(-b;a)$.', 'Étape 2 : On calcule $\\vec{n}\\cdot\\vec{u} = a\\times(-b) + b\\times a = -ab+ab = 0$.', 'Étape 3 : Le produit scalaire est nul pour toutes valeurs de $a$ et $b$ : $\\vec{n}$ est donc orthogonal à tout vecteur directeur de $d$, ce qui prouve que $\\vec{n}(a;b)$ est un vecteur normal à $d$.')),
    (2159, "Équation d'un cercle", 1, 'Donner une équation du cercle $\\mathcal{C}$ de centre $\\Omega(4 ; -2)$ et de rayon $6$.', '$\\mathcal{C} : (x-4)^2+(y+2)^2 = 36$', "Une équation d'un cercle de centre $\\Omega(a;b)$ et de rayon $r$ est $(x-a)^2+(y-b)^2=r^2$.", ('Étape 1 : Le centre est $\\Omega(4 ; -2)$ et le rayon est $r=6$, donc $r^2=36$.', 'Étape 2 : Une équation de $\\mathcal{C}$ est $(x-4)^2+(y+2)^2 = 36$.')),
    (2160, "Équation d'un cercle", 1, 'Donner une équation du cercle $\\mathcal{C}$ de centre $\\Omega(-5 ; 3)$ et de rayon $3$.', '$\\mathcal{C} : (x+5)^2+(y-3)^2 = 9$', "Une équation d'un cercle de centre $\\Omega(a;b)$ et de rayon $r$ est $(x-a)^2+(y-b)^2=r^2$.", ('Étape 1 : Le centre est $\\Omega(-5 ; 3)$ et le rayon est $r=3$, donc $r^2=9$.', 'Étape 2 : Une équation de $\\mathcal{C}$ est $(x+5)^2+(y-3)^2 = 9$.')),
    (2161, "Équation d'un cercle", 2, 'Donner une équation du cercle de diamètre $[AB]$ où $A(-2 ; 3)$ et $B(4 ; -1)$.', '$(x-1)^2+(y-1)^2 = 13$', 'Le centre est le milieu de $[AB]$ et le rayon est $\\dfrac{AB}{2}$.', ('Étape 1 : Le centre $\\Omega$ est le milieu de $[AB]$ : $\\Omega\\left(\\dfrac{-2+4}{2} ; \\dfrac{3+-1}{2}\\right) = \\Omega\\left(1 ; 1\\right)$.', 'Étape 2 : $AB^2 = (4-(-2))^2+(-1-(3))^2 = 52$, donc $r^2 = \\dfrac{AB^2}{4} = 13$.', 'Étape 3 : Une équation du cercle est $(x-1)^2+(y-1)^2 = 13$.')),
    (2162, "Équation d'un cercle", 3, 'Donner une équation du cercle de diamètre $[AB]$ où $A(1 ; 6)$ et $B(7 ; 2)$.', '$(x-4)^2+(y-4)^2 = 13$', 'Le centre est le milieu de $[AB]$ et le rayon est $\\dfrac{AB}{2}$.', ('Étape 1 : Le centre $\\Omega$ est le milieu de $[AB]$ : $\\Omega\\left(\\dfrac{1+7}{2} ; \\dfrac{6+2}{2}\\right) = \\Omega\\left(4 ; 4\\right)$.', 'Étape 2 : $AB^2 = (7-(1))^2+(2-(6))^2 = 52$, donc $r^2 = \\dfrac{AB^2}{4} = 13$.', 'Étape 3 : Une équation du cercle est $(x-4)^2+(y-4)^2 = 13$.')),
    (2163, "Équation d'un cercle", 3, "On donne l'équation $\\mathcal{C} : x^2+y^2 -8x +6y +0 = 0$. Montrer qu'il s'agit de l'équation d'un cercle dont on précisera le centre et le rayon.", 'Cercle de centre $\\Omega(4 ; -3)$ et de rayon $5$', "Mettre l'équation sous forme canonique en complétant les carrés en $x$ et en $y$.", ('Étape 1 : On complète le carré en $x$ : $x^2 -8x = (x-(4))^2-16$.', 'Étape 2 : On complète le carré en $y$ : $y^2 +6y = (y-(-3))^2-9$.', "Étape 3 : L'équation devient $(x-(4))^2+(y-(-3))^2 = 16+9-(0) = 25$, avec $25 > 0$ : c'est bien un cercle, de centre $\\Omega(4;-3)$ et de rayon $r=\\sqrt{25}=5$.")),
    (2164, "Équation d'un cercle", 3, "On donne l'équation $\\mathcal{C} : x^2+y^2 +2x -14y +22 = 0$. Montrer qu'il s'agit de l'équation d'un cercle dont on précisera le centre et le rayon.", 'Cercle de centre $\\Omega(-1 ; 7)$ et de rayon $2 \\sqrt{7}$', "Mettre l'équation sous forme canonique en complétant les carrés en $x$ et en $y$.", ('Étape 1 : On complète le carré en $x$ : $x^2 +2x = (x-(-1))^2-1$.', 'Étape 2 : On complète le carré en $y$ : $y^2 -14y = (y-(7))^2-49$.', "Étape 3 : L'équation devient $(x-(-1))^2+(y-(7))^2 = 1+49-(22) = 28$, avec $28 > 0$ : c'est bien un cercle, de centre $\\Omega(-1;7)$ et de rayon $r=\\sqrt{28}=2 \\sqrt{7}$.")),
    (2165, "Équation d'un cercle", 4, "On donne l'équation $\\mathcal{C} : x^2+y^2 -10x -2y +10 = 0$. Montrer qu'il s'agit de l'équation d'un cercle dont on précisera le centre et le rayon.", 'Cercle de centre $\\Omega(5 ; 1)$ et de rayon $4$', "Mettre l'équation sous forme canonique en complétant les carrés en $x$ et en $y$.", ('Étape 1 : On complète le carré en $x$ : $x^2 -10x = (x-(5))^2-25$.', 'Étape 2 : On complète le carré en $y$ : $y^2 -2y = (y-(1))^2-1$.', "Étape 3 : L'équation devient $(x-(5))^2+(y-(1))^2 = 25+1-(10) = 16$, avec $16 > 0$ : c'est bien un cercle, de centre $\\Omega(5;1)$ et de rayon $r=\\sqrt{16}=4$.")),
    (2166, "Équation d'un cercle", 3, "On donne l'équation $\\mathcal{C} : x^2+y^2 -6x +8y+c = 0$. Sachant que $\\mathcal{C}$ est un cercle de rayon $5$, déterminer la valeur de $c$.", '$c = 0$', 'Le rayon vérifie $r^2 = \\left(\\dfrac{a}{2}\\right)^2+\\left(\\dfrac{b}{2}\\right)^2-c$ où $a,b$ sont les coefficients de $x$ et $y$.', ('Étape 1 : Le centre du cercle est $\\Omega(3;-4)$, donc $r^2 = (3)^2+(-4)^2-c$.', 'Étape 2 : $25 = 25 - c$, donc $c = 25 - 25 = 0$.')),
    (2167, "Équation d'un cercle", 3, "On donne l'équation $\\mathcal{C} : x^2+y^2 +4x -12y+c = 0$. Sachant que $\\mathcal{C}$ est un cercle de rayon $7$, déterminer la valeur de $c$.", '$c = -9$', 'Le rayon vérifie $r^2 = \\left(\\dfrac{a}{2}\\right)^2+\\left(\\dfrac{b}{2}\\right)^2-c$ où $a,b$ sont les coefficients de $x$ et $y$.', ('Étape 1 : Le centre du cercle est $\\Omega(-2;6)$, donc $r^2 = (-2)^2+(6)^2-c$.', 'Étape 2 : $49 = 40 - c$, donc $c = 40 - 49 = -9$.')),
    (2168, "Équation d'un cercle", 2, "On donne l'équation $\\mathcal{C} : (x-2)^2+(y+5)^2 = 20$. Préciser le centre et le rayon exact de ce cercle.", 'Centre $\\Omega(2 ; -5)$, rayon $2 \\sqrt{5}$', 'Le rayon est $r = \\sqrt{r^2}$, à simplifier si possible en faisant apparaître un carré parfait.', ("Étape 1 : L'équation est sous forme canonique $(x-(2))^2+(y-(-5))^2=20$, donc le centre est $\\Omega(2;-5)$.", 'Étape 2 : Le rayon vérifie $r^2=20$, donc $r=\\sqrt{20}=2 \\sqrt{5}$.')),
    (2169, "Équation d'un cercle", 2, "On donne l'équation $\\mathcal{C} : (x+3)^2+(y-1)^2 = 18$. Préciser le centre et le rayon exact de ce cercle.", 'Centre $\\Omega(-3 ; 1)$, rayon $3 \\sqrt{2}$', 'Le rayon est $r = \\sqrt{r^2}$, à simplifier si possible en faisant apparaître un carré parfait.', ("Étape 1 : L'équation est sous forme canonique $(x-(-3))^2+(y-(1))^2=18$, donc le centre est $\\Omega(-3;1)$.", 'Étape 2 : Le rayon vérifie $r^2=18$, donc $r=\\sqrt{18}=3 \\sqrt{2}$.')),
    (2170, "Équation d'un cercle", 2, 'Vrai ou faux ? Le point $M(4 ; 2)$ appartient au cercle $\\mathcal{C} : (x-1)^2+(y+2)^2 = 25$. Justifier.', 'Vrai', 'Calculer $(x_M-a)^2+(y_M-b)^2$ et comparer au rayon au carré $r^2$.', ('Étape 1 : On calcule $(4-(1))^2+(2-(-2))^2 = 25$.', "Étape 2 : On trouve $25$, qui est bien égal à $r^2=25$ : le point $M$ appartient donc à $\\mathcal{C}$. L'affirmation est vraie.")),
    (2171, "Équation d'un cercle", 2, 'Vrai ou faux ? Le point $M(3 ; 2)$ appartient au cercle $\\mathcal{C} : (x-0)^2+(y-3)^2 = 13$. Justifier.', 'Faux', 'Calculer $(x_M-a)^2+(y_M-b)^2$ et comparer au rayon au carré $r^2$.', ('Étape 1 : On calcule $(3-(0))^2+(2-(3))^2 = 10$.', "Étape 2 : On trouve $10 \\neq 13 = r^2$ : le point $M$ n'appartient donc pas à $\\mathcal{C}$. L'affirmation est fausse.")),
    (2172, "Équation d'un cercle", 3, 'Vrai ou faux ? Le point $M(-1 ; 3)$ appartient au cercle $\\mathcal{C} : (x+4)^2+(y-1)^2 = 10$. Justifier.', 'Faux', 'Calculer $(x_M-a)^2+(y_M-b)^2$ et comparer au rayon au carré $r^2$.', ('Étape 1 : On calcule $(-1-(-4))^2+(3-(1))^2 = 13$.', "Étape 2 : On trouve $13 \\neq 10 = r^2$ : le point $M$ n'appartient donc pas à $\\mathcal{C}$. L'affirmation est fausse.")),
    (2173, "Équation d'un cercle", 3, 'Pour mettre $\\mathcal{C} : x^2+y^2-6x+4y-3=0$ sous forme canonique, un élève écrit : « $x^2-6x=(x-3)^2$ et $y^2+4y=(y+2)^2$, donc $\\mathcal{C} : (x-3)^2+(y+2)^2=3$ ». Identifier et corriger son erreur.', '$\\mathcal{C} : (x-3)^2+(y+2)^2 = 16$, cercle de centre $\\Omega(3;-2)$ et de rayon $4$', 'En complétant le carré, il ne faut pas oublier le terme constant retranché : $x^2-6x = (x-3)^2-9$, pas $(x-3)^2$.', ("Étape 1 : L'élève a oublié les constantes issues de la mise sous forme canonique : $x^2-6x=(x-3)^2-9$ et $y^2+4y=(y+2)^2-4$, pas simplement $(x-3)^2$ et $(y+2)^2$.", "Étape 2 : L'équation devient $(x-3)^2-9+(y+2)^2-4-3=0$, soit $(x-3)^2+(y+2)^2 = 9+4+3 = 16$.", 'Étape 3 : $\\mathcal{C}$ est donc le cercle de centre $\\Omega(3;-2)$ et de rayon $\\sqrt{16}=4$, et non un cercle de rayon $\\sqrt{3}$.')),
    (2174, "Équation d'un cercle", 2, 'Pour trouver le rayon du cercle $\\mathcal{C} : (x+2)^2+(y-5)^2 = 11$, un élève écrit : « le rayon est $r = 11$ ». Identifier et corriger son erreur.', '$r = \\sqrt{11}$', "Dans l'équation canonique $(x-a)^2+(y-b)^2=r^2$, le membre de droite est $r^2$, pas $r$.", ("Étape 1 : L'élève a confondu $r^2$ et $r$ : dans l'équation $(x-a)^2+(y-b)^2=r^2$, le nombre $11$ est $r^2$, pas $r$.", 'Étape 2 : Il faut donc prendre la racine carrée : $r = \\sqrt{11}$.', "Étape 3 : Le rayon correct est $r=\\sqrt{11}$ (qui n'est pas un entier), et non $11$.")),
    (2175, "Équation d'un cercle", 2, "Une borne Wi-Fi est installée au point $\\Omega(3 ; 2)$ (coordonnées en dizaines de mètres) et couvre un disque de rayon $5$. Un ordinateur portable se trouve au point $P(6 ; 6)$. L'ordinateur est-il dans la zone de couverture (c'est-à-dire à l'intérieur ou sur le cercle limite) ?", 'Oui, $P$ est exactement sur le cercle limite de la zone de couverture', 'Calculer $\\Omega P^2$ et comparer au carré du rayon.', ('Étape 1 : Une équation du cercle limite de la zone de couverture est $(x-3)^2+(y-2)^2=25$.', 'Étape 2 : On calcule $(6-3)^2+(6-2)^2 = 9+16 = 25$.', "Étape 3 : Comme $25=25$, le point $P$ appartient exactement au cercle limite : l'ordinateur est à la limite de la zone de couverture, donc encore couvert.")),
    (2176, "Équation d'un cercle", 3, 'Un radar routier situé au point $A(-2 ; 4)$ (coordonnées en kilomètres) a une portée de détection de rayon $10$. Une voiture roule au point $V(4 ; -2)$. Est-elle détectée par le radar ?', "Oui, la voiture est détectée : elle se trouve à l'intérieur de la zone de portée", 'Comparer $AV^2$ au carré du rayon de portée.', ('Étape 1 : Le cercle de portée a pour équation $(x+2)^2+(y-4)^2=100$.', 'Étape 2 : On calcule $(4+2)^2+(-2-4)^2 = 36+36 = 72$.', "Étape 3 : Comme $72 < 100$, le point $V$ est à l'intérieur du disque de portée : la voiture est donc bien détectée par le radar.")),
    (2177, "Équation d'un cercle", 3, "On donne les points $A(-1 ; -1)$, $B(5 ; 3)$ et $P(2 ; -2)$. Le cercle $\\mathcal{C}$ est l'ensemble des points $M$ du plan tels que $\\vec{MA}\\cdot\\vec{MB}=0$. Caractériser $\\mathcal{C}$ (centre, rayon), puis déterminer si $P$ appartient à $\\mathcal{C}$.", "$\\mathcal{C}$ a pour centre $\\Omega(2;1)$ et rayon $\\sqrt{13}$ ; $P$ n'appartient pas à $\\mathcal{C}$", "L'ensemble des points $M$ tels que $\\vec{MA}\\cdot\\vec{MB}=0$ est le cercle de diamètre $[AB]$.", ("Étape 1 : L'ensemble $\\mathcal{C}$ est le cercle de diamètre $[AB]$, de centre le milieu $\\Omega$ de $[AB]$ et de rayon $\\dfrac{AB}{2}$.", 'Étape 2 : $\\Omega\\left(\\dfrac{-1+5}{2};\\dfrac{-1+3}{2}\\right) = \\Omega(2;1)$, et $AB^2=(5-(-1))^2+(3-(-1))^2=52$, donc $r^2=\\dfrac{AB^2}{4}=13$.', 'Étape 3 : On calcule $(2-(2))^2+(-2-(1))^2 = 9$, à comparer à $r^2=13$.', "Étape 4 : $9 \\neq 13$ : le point $P$ n'appartient donc pas à $\\mathcal{C}$.")),
    (2178, "Équation d'un cercle", 3, "On donne les points $A(0 ; 2)$, $B(6 ; 2)$ et $P(3 ; 5)$. Le cercle $\\mathcal{C}$ est l'ensemble des points $M$ du plan tels que $\\vec{MA}\\cdot\\vec{MB}=0$. Caractériser $\\mathcal{C}$ (centre, rayon), puis déterminer si $P$ appartient à $\\mathcal{C}$.", '$\\mathcal{C}$ a pour centre $\\Omega(3;2)$ et rayon $\\sqrt{9}$ ; $P$ appartient à $\\mathcal{C}$', "L'ensemble des points $M$ tels que $\\vec{MA}\\cdot\\vec{MB}=0$ est le cercle de diamètre $[AB]$.", ("Étape 1 : L'ensemble $\\mathcal{C}$ est le cercle de diamètre $[AB]$, de centre le milieu $\\Omega$ de $[AB]$ et de rayon $\\dfrac{AB}{2}$.", 'Étape 2 : $\\Omega\\left(\\dfrac{0+6}{2};\\dfrac{2+2}{2}\\right) = \\Omega(3;2)$, et $AB^2=(6-(0))^2+(2-(2))^2=36$, donc $r^2=\\dfrac{AB^2}{4}=9$.', 'Étape 3 : On calcule $(3-(3))^2+(5-(2))^2 = 9$, à comparer à $r^2=9$.', 'Étape 4 : $9 = 9$ : le point $P$ appartient donc à $\\mathcal{C}$.')),
    (2179, "Équation d'un cercle", 3, "On donne $\\mathcal{C} : x^2+y^2-4x+10y+4=0$. Un élève trouve le centre et le rayon en complétant le carré ; un autre utilise directement les formules $\\Omega\\left(-\\dfrac{a}{2};-\\dfrac{b}{2}\\right)$ et $r=\\sqrt{\\left(\\dfrac{a}{2}\\right)^2+\\left(\\dfrac{b}{2}\\right)^2-c}$ avec $a=-4$, $b=10$, $c=4$. Mener les deux méthodes et vérifier qu'elles donnent le même résultat.", 'Les deux méthodes donnent $\\Omega(2;-5)$ et $r=5$', 'Les deux méthodes reposent sur la même identité algébrique ; seule la présentation diffère.', ('Étape 1 (carré) : $x^2-4x=(x-2)^2-4$ et $y^2+10y=(y+5)^2-25$, donc $\\mathcal{C} : (x-2)^2+(y+5)^2 = 4+25-4=25$, soit $\\Omega(2;-5)$ et $r=\\sqrt{25}=5$.', 'Étape 2 (formule directe) : $\\Omega\\left(-\\dfrac{-4}{2};-\\dfrac{10}{2}\\right) = \\Omega(2;-5)$ et $r=\\sqrt{\\left(\\dfrac{-4}{2}\\right)^2+\\left(\\dfrac{10}{2}\\right)^2-4} = \\sqrt{4+25-4}=\\sqrt{25}=5$.', 'Étape 3 : Les deux méthodes donnent bien le même centre $\\Omega(2;-5)$ et le même rayon $r=5$ : la formule directe est plus rapide mais repose sur le même principe que la méthode par complétion du carré.')),
    (2180, "Équation d'un cercle", 5, "Soit l'équation $x^2+y^2+ax+by+c=0$ avec $a,b,c$ réels. Démontrer que si $a^2+b^2-4c>0$, alors cette équation est celle d'un cercle dont on précisera le centre et le rayon en fonction de $a$, $b$ et $c$.", "C'est le cercle de centre $\\Omega\\left(-\\dfrac{a}{2};-\\dfrac{b}{2}\\right)$ et de rayon $r=\\dfrac{\\sqrt{a^2+b^2-4c}}{2}$", 'Compléter le carré en $x$ puis en $y$ pour faire apparaître une somme de deux carrés égale à une constante.', ('Étape 1 : $x^2+ax = \\left(x+\\dfrac{a}{2}\\right)^2-\\dfrac{a^2}{4}$ et $y^2+by=\\left(y+\\dfrac{b}{2}\\right)^2-\\dfrac{b^2}{4}$.', "Étape 2 : L'équation devient $\\left(x+\\dfrac{a}{2}\\right)^2+\\left(y+\\dfrac{b}{2}\\right)^2 = \\dfrac{a^2}{4}+\\dfrac{b^2}{4}-c = \\dfrac{a^2+b^2-4c}{4}$.", "Étape 3 : Comme $a^2+b^2-4c>0$ par hypothèse, le membre de droite est strictement positif : c'est bien l'équation d'un cercle, de centre $\\Omega\\left(-\\dfrac{a}{2};-\\dfrac{b}{2}\\right)$ et de rayon $r=\\sqrt{\\dfrac{a^2+b^2-4c}{4}}=\\dfrac{\\sqrt{a^2+b^2-4c}}{2}$.")),
)
